SPECIMENS.forEach((s, i) => { s.num = i + 1; });

export const BY_ID = Object.fromEntries(SPECIMENS.map(s => [s.id, s]));
export const GROUP_BY_ID = Object.fromEntries(GROUPS.map(g => [g.id, g]));
export const KINGDOM_BY_ID = Object.fromEntries(KINGDOMS.map(k => [k.id, k]));
export const TOTAL = SPECIMENS.length;

export const kingdomOf = s => GROUP_BY_ID[s.g].k;
export const isRockLike = s => { const k = kingdomOf(s); return k === "rocks" || k === "space"; };
export const hardnessText = s => !s.h ? "" : s.h[0] === s.h[1] ? String(s.h[0]) : `${s.h[0]} – ${s.h[1]}`;
export const hardnessMid = s => s.h ? (s.h[0] + s.h[1]) / 2 : null;
